import type { ProductFeature, SourceRow, SourceState } from '@moviq/contracts';

/** One source of the fixtures, written as offsets from the instant they are built for. */
export interface Spec {
  readonly id: string;
  readonly title: string;
  readonly provider: string;
  readonly kind: SourceRow['kind'];
  readonly rhythm: SourceRow['rhythm'];
  readonly state: SourceState;
  readonly evidence: string;
  /** Seconds before now of the data time, or null when no data was ever received. */
  readonly age: number | null;
  readonly limits: readonly [number, number, number];
  readonly interval: number;
  readonly next: number | null;
  readonly reason: SourceRow['nextRunReason'];
  readonly coverage: string | null;
  readonly error: { code: string; detail: string; ago: number } | null;
  readonly failures: number;
  readonly latency: number | null;
  readonly interested: boolean;
  readonly consumers: readonly ProductFeature[];
}

